async (page) => {
 const checks=[],contractOutputs=[];
 const render=async id=>{await page.setViewportSize({width:1440,height:900});await page.evaluate(id=>window.DW_PROTOTYPE.renderScreen(id),id);await page.waitForFunction(id=>window.DW_READY===id,id);};
 const click=async action=>{await page.locator('[data-query-action="'+action+'"]').click();await page.waitForFunction(()=>window.DW_READY==='mcp-query');};
 const verify=async(name,fn)=>{if(!await page.evaluate(fn))throw Error(name);checks.push({name,result:'pass'});};
 const collect=async(name,fragment,fn,queryType='page',contextFn=null)=>{const value=await page.evaluate(fn),row={name,schema:'query.schema.json#/$defs/'+fragment,value};if(queryType)row.queryType=queryType;if(contextFn)row.context=await page.evaluate(contextFn);contractOutputs.push(row);};
 const context=()=>{const q=window.DW_QUERIES;return {params:q.state.lastRequest,source:q.state.source,rows:q.api.rows(q.state.source.collectionId),principal:'client-synthetic',workspace:'workspace-demo',authorizationVersion:1,authorized:true,now:q.state.page.querySnapshot.snapshotAt,querySnapshot:q.state.page.querySnapshot};};
 await render('mcp-query');
 await verify('集合查询默认每页五十项',()=>{const q=window.DW_QUERIES.state;return q.pageSize===50&&q.page.items.length===50&&q.page.matchedCount===126&&q.page.nextCursor!==null&&q.pageIndex===0;});
 await collect('查询首页','page',()=>window.DW_QUERIES.state.page,'page',context);
 await collect('查询参数','readParams',()=>window.DW_QUERIES.state.lastRequest,'request',context);
 const first=await page.evaluate(()=>window.DW_QUERIES.state.page);
 await click('next');
 await verify('续页使用同一快照且不重复成员',()=>{const q=window.DW_QUERIES.state;return q.pageIndex===1&&q.page.items[0].index===50&&q.page.items.at(-1).index===99&&q.pages[0].querySnapshot.snapshotId===q.page.querySnapshot.snapshotId;});
 await collect('实际续页结果','page',()=>window.DW_QUERIES.state.page,'page',()=>{const q=window.DW_QUERIES,c={params:q.state.lastRequest,source:q.state.source,rows:q.api.rows(q.state.source.collectionId),principal:'client-synthetic',workspace:'workspace-demo',authorizationVersion:1,authorized:true,now:q.state.page.querySnapshot.snapshotAt,querySnapshot:q.state.page.querySnapshot};c.cursorBinding={...q.state.lastRequest,principal:c.principal,workspace:c.workspace,authorizationVersion:1,lastIndex:49,expiresAt:q.state.page.querySnapshot.expiresAt};return c;});
 const second=await page.evaluate(()=>window.DW_QUERIES.state.page);
 await page.evaluate(()=>window.DW_QUERIES.api.append('templateNames',{candidateId:'added-later',name:'新增报表入口',source:'manual',reason:null,conflict:false}));
 await click('next');
 await verify('新增成员不插入既有查询末页',()=>{const q=window.DW_QUERIES.state;return q.page.items.length===26&&q.page.matchedCount===126&&q.page.nextCursor===null&&q.page.items.at(-1).index===125;});
 if(await page.locator('[data-query-action="next"]').isEnabled())throw Error('末页仍可继续翻页');checks.push({name:'末页关闭下一页操作',result:'pass'});
 await click('previous');
 const previous=await page.evaluate(()=>window.DW_QUERIES.state.page);
 if(JSON.stringify(previous)!==JSON.stringify(second))throw Error('返回已读取页改变了内容');checks.push({name:'返回上一页使用同一已读结果',result:'pass'});
 await verify('重复游标返回相同页面与后续游标',()=>{const q=window.DW_QUERIES;return JSON.stringify(q.api.read(q.state.lastRequest))===JSON.stringify(q.state.page);});
 await click('fresh');await verify('重新查询获取当前来源版本',()=>window.DW_QUERIES.state.page.matchedCount===127);
 await page.locator('[data-query-field="status"]').selectOption({label:'无冲突'});
 if(await page.locator('[data-query-action="next"]').isEnabled())throw Error('修改条件后仍可沿用旧游标');checks.push({name:'条件改变后停止使用旧分页',result:'pass'});
 await click('search');
 await verify('布尔假值条件在服务端过滤',()=>{const q=window.DW_QUERIES.state;return q.lastRequest.filter.conflict===false&&q.page.items.every(item=>item.value.conflict===false)&&q.page.matchedCount<127;});
 await collect('无冲突条件结果','page',()=>window.DW_QUERIES.state.page,'page',context);
 await page.locator('[data-query-field="text"]').fill('不存在的模板');await page.locator('[data-query-field="text"]').press('Tab');await click('search');
 await verify('空查询返回明确末页',()=>{const p=window.DW_QUERIES.state.page;return p.items.length===0&&p.matchedCount===0&&p.nextCursor===null;});
 await collect('空查询结果','page',()=>window.DW_QUERIES.state.page,'page',context);
 await page.locator('[data-query-field="text"]').fill('报表');await page.locator('[data-query-field="text"]').press('Tab');await page.locator('[data-query-field="pageSize"]').selectOption('10');await page.locator('[data-query-field="order"]').selectOption({label:'反向顺序'});await click('search');
 await verify('每页数量与排序进入查询参数',()=>{const q=window.DW_QUERIES.state;return q.lastRequest.pageSize===10&&q.lastRequest.order==='desc'&&q.page.items.length<=10&&q.page.items.every((item,i,all)=>!i||all[i-1].index>item.index);});
 await page.evaluate(()=>{const q=window.DW_QUERIES;const request={...q.state.lastRequest,cursor:null,includeTotal:false};q.state.noTotalRequest=request;q.state.noTotalPage=q.api.read(request);});
 await verify('筛选查询可按需省略总数计算',()=>{const p=window.DW_QUERIES.state.noTotalPage;return p.matchedCount===null&&p.countState==='notComputed';});
 await collect('未计算总数的查询','page',()=>window.DW_QUERIES.state.noTotalPage,'page',()=>{const q=window.DW_QUERIES;return {params:q.state.noTotalRequest,source:q.state.source,rows:q.api.rows(q.state.source.collectionId),authorized:true,now:q.state.noTotalPage.querySnapshot.snapshotAt,querySnapshot:q.state.noTotalPage.querySnapshot};});
 await render('mcp-query');
 for(const label of ['流程诊断','运行准备条件','运行调用帧','输入效果','模板命名预览','已保存模板','匹配候选','导入对象','已安装语言']){
  await page.locator('[data-query-field="kind"]').selectOption({label});
  await collect(label+'实际查询页','page',()=>window.DW_QUERIES.state.page,'page',context);
 }
 checks.push({name:'九种集合分别返回类型化查询页',result:'pass'});
 await render('mcp-query-expired');await verify('过期续页保留条件并报告实际原因',()=>{const q=window.DW_QUERIES.state;return q.error==='CURSOR_EXPIRED'&&q.page.items.length===50;});
 await click('fresh');await verify('重新查询清理过期游标',()=>{const q=window.DW_QUERIES.state;return q.error===''&&q.pageIndex===0&&q.lastRequest.cursor===null;});
 await render('mcp-query-error');await verify('条件不一致的续页被拒绝',()=>window.DW_QUERIES.state.error==='CURSOR_QUERY_MISMATCH');
 await click('fresh');await verify('修正后使用新的排序重新查询',()=>{const q=window.DW_QUERIES.state;return q.error===''&&q.page.items[0].index===125&&q.lastRequest.order==='desc';});
 await render('mcp-query');
 await verify('查询游标不能跨客户端复用',()=>{const q=window.DW_QUERIES;try{q.api.read({...q.state.lastRequest,cursor:q.state.page.nextCursor},{principal:'another-client',workspace:'workspace-demo',authorizationVersion:1});return false;}catch(error){return error.message==='ACCESS_DENIED';}});
 await verify('查询游标不能跨工作空间复用',()=>{const q=window.DW_QUERIES;try{q.api.read({...q.state.lastRequest,cursor:q.state.page.nextCursor},{principal:'client-synthetic',workspace:'another-workspace',authorizationVersion:1});return false;}catch(error){return error.message==='ACCESS_DENIED';}});
 await verify('分页参数拒绝零值和无上限值',()=>{const q=window.DW_QUERIES;return [0,-1,10000].every(pageSize=>{try{q.api.read({...q.state.lastRequest,pageSize,cursor:null});return false;}catch(error){return error.message==='INVALID_PARAMS';}});});
 await verify('集合首页也检查读取者与工作空间',()=>{const q=window.DW_QUERIES;try{q.api.read({...q.state.lastRequest,cursor:null},{principal:'another-client',workspace:'another-workspace',authorizationVersion:1});return false;}catch(error){return error.message==='COLLECTION_NOT_FOUND';}});
 await verify('旧条件的迟到结果不覆盖当前页',()=>{const q=window.DW_QUERIES,before=JSON.stringify(q.state.page);return !q.accept({items:[]},q.state.version-1)&&JSON.stringify(q.state.page)===before;});
 await page.evaluate(()=>{const q=window.DW_QUERIES;q.state.closeRequest={snapshotId:q.state.page.querySnapshot.snapshotId};q.state.closeResult=q.api.close(q.state.closeRequest);});
 await collect('关闭查询参数','closeParams',()=>window.DW_QUERIES.state.closeRequest,null);
 await collect('关闭查询结果','closeResult',()=>window.DW_QUERIES.state.closeResult,'close');
 await verify('关闭后的游标失效且重复关闭幂等',()=>{const q=window.DW_QUERIES;const repeated=q.api.close(q.state.closeRequest);try{q.api.read({...q.state.lastRequest,cursor:q.state.page.nextCursor});return false;}catch(error){return repeated.closed&&error.message==='CURSOR_EXPIRED';}});
 await render('mcp-query');await verify('撤权后不能继续读取原查询',()=>{const q=window.DW_QUERIES;q.api.revoke(q.state.source.collectionId);try{q.api.read({...q.state.lastRequest,cursor:q.state.page.nextCursor});return false;}catch(error){return error.message==='ACCESS_DENIED';}});
 return {checks,contractOutputs};
}
